const assert = require('node:assert/strict');
const { DocumentRepository } = require('../.build/repository');
const { DocumentService } = require('../.build/service');

function fresh() {
  const repo = new DocumentRepository([
    { id: 'own', tenant: 'a', owner: 'ed', deleted: false, archived: false },
    { id: 'other', tenant: 'a', owner: 'someone', deleted: false, archived: false },
    { id: 'deleted', tenant: 'a', owner: 'ed', deleted: true, archived: false },
    { id: 'foreign', tenant: 'b', owner: 'ed', deleted: false, archived: false },
  ]);
  return { repo, service: new DocumentService(repo) };
}

const admin = { tenant: 'a', user: 'admin', role: 'admin' };
const editor = { tenant: 'a', user: 'ed', role: 'editor' };
const viewer = { tenant: 'a', user: 'v', role: 'viewer' };

// not found: missing, deleted, foreign — even for admin
for (const actor of [admin, editor, viewer]) {
  for (const id of ['missing', 'deleted', 'foreign']) {
    const { repo, service } = fresh();
    assert.throws(() => service.archive(actor, id), err => err instanceof Error && err.message === 'not found');
    assert.deepEqual(repo.audit, []);
    assert.equal(repo.documents.every(d => !d.archived), true);
  }
}

// admin may archive any visible document, including one owned by someone else
{
  const { repo, service } = fresh();
  service.archive(admin, 'other');
  assert.equal(repo.documents.find(d => d.id === 'other').archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'admin', document: 'other' }]);
}

// editor may archive own document
{
  const { repo, service } = fresh();
  service.archive(editor, 'own');
  assert.equal(repo.documents.find(d => d.id === 'own').archived, true);
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'own' }]);
}

// editor forbidden on other's visible document
{
  const { repo, service } = fresh();
  assert.throws(() => service.archive(editor, 'other'), err => err instanceof Error && err.message === 'forbidden');
  assert.deepEqual(repo.audit, []);
  assert.equal(repo.documents.find(d => d.id === 'other').archived, false);
}

// viewer forbidden on any visible document, even own-owned
for (const id of ['own', 'other']) {
  const { repo, service } = fresh();
  assert.throws(() => service.archive(viewer, id), err => err instanceof Error && err.message === 'forbidden');
  assert.deepEqual(repo.audit, []);
  assert.equal(repo.documents.find(d => d.id === id).archived, false);
}

// repeat archive: no-op, permission still enforced first even when already archived
{
  const { repo, service } = fresh();
  service.archive(admin, 'other');
  service.archive(admin, 'other');
  assert.deepEqual(repo.audit, [{ actor: 'admin', document: 'other' }]);
  assert.throws(() => service.archive(editor, 'other'), /forbidden/);
  assert.throws(() => service.archive(viewer, 'other'), /forbidden/);
  assert.deepEqual(repo.audit, [{ actor: 'admin', document: 'other' }]);
  assert.equal(repo.documents.find(d => d.id === 'other').archived, true);
}
{
  const { repo, service } = fresh();
  service.archive(editor, 'own');
  service.archive(editor, 'own');
  assert.deepEqual(repo.audit, [{ actor: 'ed', document: 'own' }]);
}

console.log('checks/auth.cjs: ok');

